pub fn reconcile_ledger(opening: i64, entries: &[(i64, i64, i64)]) -> Option<i64> {
    let mut seen_ids: HashSet<i64> = HashSet::new();
    let mut total: i64 = opening;

    for (id, kind, amount) in entries {
        // Validate kind
        if kind != 1 && kind != -1 {
            return None;
        }

        // Validate amount
        if amount <= 0 {
            return None;
        }

        // Validate id uniqueness
        if seen_ids.contains(id) {
            return None;
        }
        seen_ids.insert(id);

        // Apply transaction
        if kind == 1 {
            total += amount;
        } else {
            total -= amount;
        }
    }

    Some(total)
}

